    if op.has_trait(Trait.ISOLATED_FROM_ABOVE) and op.name != "builtin.module":
        saved_state = self._name_state
        self._name_state = SSANameState(preserve_names=saved_state.preserve_names)
    try:
        header = self._format_op_header(op)
